// @FIGURE_CODE_BEGIN
const W = 820;
const H = 600;
const draw = SVG().addTo('#container').size('100%', '100%').viewbox(0, 0, W, H);

// ── Global Colors & Styles ──
const colNaCl = '#cce0ff';
const colCl2Hood = '#d9ebd3';
const colNaLiquid = '#f2d1e0';
const colAnode = '#e67e22';
const colCathode = '#95a5a6';
const colWall = '#7f8c8d';
const colWallStroke = '#2c3e50';
const strokeThick = { width: 3, color: colWallStroke, linecap: 'round', linejoin: 'round' };

// ── Draw Layers (Z-order) ──
const layerBgFills = draw.group();
const layerMesh = draw.group();
const layerElectrodes = draw.group();
const layerWalls = draw.group();
const layerActiveEffects = draw.group();
const layerWires = draw.group();
const layerUI = draw.group();

// ── Background Fills (Fluids) ──

// 1. Molten NaCl Main Bath (Light Blue)
// Fills the main chamber from Y=250 down to the floor at 480
layerBgFills.polygon('140,250 580,250 580,480 140,480').fill(colNaCl);

// 2. Liquid Na Floating Layers (Pink)
// Floats on top of the blue salt between walls and the hood
layerBgFills.polygon('140,220 220,220 220,250 140,250').fill(colNaLiquid); // Left side
layerBgFills.polygon('480,220 580,220 580,250 480,250').fill(colNaLiquid); // Right side

// 3. Liquid Na Collector Path (Pink) - Clean enclosed side vessel
const naCollectorPath = [
  'M 580 220',
  'L 610 220',
  'L 610 160',
  'A 20 20 0 0 1 650 160',
  'L 650 280',
  'L 640 310',
  'L 640 340',
  'L 740 340',
  'L 740 320',
  'L 620 320',
  'L 620 310',
  'L 610 280',
  'L 610 250',
  'L 580 250',
  'Z'
].join(' ');
layerBgFills.path(naCollectorPath).fill(colNaLiquid);

// 4. Cl₂ Gas Hood Interior (Green)
// Covers the central area, pushing the liquid level down to Y=280
const cl2Path = [
  'M 220 280',             // Bottom left opening
  'L 310 200',             // Taper up to neck
  'L 310 80',              // Up neck
  'L 700 80',              // Horizontal pipe bottom
  'L 700 50',              // Horizontal pipe top
  'L 390 50',              // Back to neck right side
  'L 390 200',             // Down neck
  'L 480 280',             // Taper down to bottom right
