].join(' ');
layerBgFills.path(cl2Path).fill(colCl2Hood);


// ── Main Chamber Walls & Piping ──
const wallFill = { fill: colWall, stroke: colWallStroke, 'stroke-width': 3, linejoin: 'round' };

// Main structure blocks
layerWalls.rect(20, 280).move(120, 200).attr(wallFill);        // Left wall
layerWalls.rect(460, 20).move(120, 480).attr(wallFill);        // Base floor
layerWalls.rect(20, 20).move(580, 200).attr(wallFill);         // Right wall (upper)
layerWalls.rect(20, 230).move(580, 250).attr(wallFill);        // Right wall (lower)

// Lid sections
layerWalls.rect(190, 20).move(120, 180).attr(wallFill);        // Lid left (to 310)
layerWalls.rect(110, 20).move(390, 180).attr(wallFill);        // Lid middle (to 500)
layerWalls.rect(60, 20).move(540, 180).attr(wallFill);         // Lid right (to 600)

// Salt Inlet (Capped Chamber)
layerWalls.rect(40, 30).move(500, 150).fill('#ecf0f1').stroke(strokeThick);
layerWalls.rect(50, 6).move(495, 144).fill('#bdc3c7').stroke(strokeThick); // Flange
layerWalls.rect(10, 20).move(515, 124).fill('#bdc3c7').stroke(strokeThick); // Rod
layerWalls.rect(30, 6).move(505, 118).fill('#bdc3c7').stroke(strokeThick); // Handle

// Cl2 Hood Outline
layerWalls.path('M 220 280 L 310 200 L 310 80 L 700 80').fill('none').stroke(strokeThick);
layerWalls.path('M 480 280 L 390 200 L 390 50 L 700 50').fill('none').stroke(strokeThick);

// Na Collector Outline
layerWalls.path('M 580 220 L 610 220 L 610 160 A 20 20 0 0 1 650 160 L 650 280 L 640 310 L 640 340 L 740 340').fill('none').stroke(strokeThick);
layerWalls.path('M 580 250 L 610 250 L 610 280 L 620 310 L 620 320 L 740 320').fill('none').stroke(strokeThick);

// Liquid surface separator lines
layerWalls.line(140, 220, 220, 220).stroke({width: 1.5, color: '#c49eb0'});
layerWalls.line(480, 220, 580, 220).stroke({width: 1.5, color: '#c49eb0'});


// ── Electrodes ──
// Anode (+)
const anodeGroup = layerElectrodes.group();
const anodeShape = anodeGroup.path('M 290 340 L 410 340 L 410 380 L 370 380 L 370 500 L 330 500 L 330 380 L 290 380 Z')
  .fill(colAnode).stroke({width: 2, color: '#333'});
anodeShape.css('cursor', 'pointer')
  .on('click', () => showPopup('Anode (Oxidation)', 'At the positive anode, chloride ions lose electrons to form chlorine gas:\n\n2Cl⁻ → Cl₂ + 2e⁻'))
  .on('mousemove', e => showTooltip('Anode (Click for half-reaction)', e))
  .on('mouseleave', () => hideTooltip());

// Cathodes (-)
const cathodeGroup = layerElectrodes.group();
[
  {x: 150, y: 310, w: 30, h: 120}, // Left block
  {x: 70,  y: 350, w: 80, h: 30},  // Left shaft
  {x: 520, y: 310, w: 30, h: 120}, // Right block
  {x: 550, y: 350, w: 80, h: 30}   // Right shaft
].forEach(rect => {
  const c = cathodeGroup.rect(rect.w, rect.h).move(rect.x, rect.y).fill(colCathode).stroke({width: 2, color: '#333'});
