}


// ── Active Effects (Bubbles, Drops, Flow Arrows) ──
const bubblesGroup = layerActiveEffects.group();
const bubblePositions = [
  [310, 330], [330, 320], [350, 325], [370, 315], [390, 325],
  [320, 290], [340, 285], [360, 295], [380, 290],
  [335, 250], [355, 260], [365, 240],
  [345, 210], [355, 200], [360, 220],
  [340, 170], [350, 150], [360, 160],
  [345, 120], [355, 100], [350, 80]
];
bubblePositions.forEach(([x, y]) => {
  bubblesGroup.circle(6).center(x, y).fill('#fff59d').stroke({width: 1, color: '#f39c12'});
