const naDropsGroup = layerActiveEffects.group();
const dropPositions = [
  [185, 320], [195, 300], [185, 280], [195, 260], [190, 240], // Left rise
  [510, 320], [500, 300], [510, 280], [500, 260], [505, 240]  // Right rise
];
dropPositions.forEach(([x, y]) => {
  naDropsGroup.circle(6).center(x, y).fill('#ffebf5').stroke({width: 1, color: '#c9779a'});
