// Always visible salt crystals in the inlet
const saltDrops = layerActiveEffects.group();
[[510, 155], [525, 160], [515, 165], [530, 170], [520, 175]].forEach(([x, y]) => {
  saltDrops.circle(4).center(x, y).fill('#fff').stroke({width: 1, color: '#aaa'});
