// Prominent flow arrows
// Central Cl2 upward flow inside hood
layerUI.path('M 342 230 L 358 230 L 358 140 L 375 140 L 350 100 L 325 140 L 342 140 Z').fill('#2c3e50');

// Cl2 Outlet Right Arrow
layerUI.line(700, 65, 765, 65).stroke({width: 3, color: '#2c3e50'});
layerUI.polygon('780,65 765,58 765,72').fill('#2c3e50');

// Na Outlet Right Arrow
layerUI.line(740, 330, 785, 330).stroke({width: 3, color: '#2c3e50'});
layerUI.polygon('800,330 785,323 785,337').fill('#2c3e50');


// ── Wires and Voltage Source ──
const wireStyle = { width: 4, color: '#95a5a6', linecap: 'round', linejoin: 'round' };
const wirePos = layerWires.path('M 350 500 L 350 560 L 660 560 L 660 550').fill('none').stroke(wireStyle);
const wireNeg1 = layerWires.path('M 70 365 L 40 365 L 40 580 L 740 580 L 740 550').fill('none').stroke(wireStyle);
const wireNeg2 = layerWires.path('M 630 365 L 740 365 L 740 480').fill('none').stroke(wireStyle);

// Voltage Box
layerWires.rect(140, 70).move(630, 480).fill('#222').stroke({width: 3, color: '#000'});
layerWires.text("Voltage\nsource").move(700, 495).font({family: 'sans-serif', size: 18, fill: '#fff', anchor: 'middle'}).dy(-14);
layerWires.rect(12, 8).move(654, 550).fill('#e74c3c'); // + Terminal
layerWires.rect(8, 12).move(740, 520).fill('#3498db'); // - Terminal


// ── UI Labels and Leaders ──
function addLabel(text, x, y, lx, ly) {
  if (lx !== undefined && ly !== undefined) {
    layerUI.line(x, y, lx, ly).stroke({width: 2, color: '#333'});
    layerUI.circle(6).center(lx, ly).fill('#333');
  }
  layerUI.text(text).move(x, y).font({family: 'sans-serif', size: 18, weight: 'bold', anchor: 'middle'}).attr({
    'paint-order': 'stroke',
    'stroke': '#fff',
    'stroke-width': 5,
    'stroke-linejoin': 'round'
  });
}

// Cleanly positioned labels pointing outside the structure
addLabel('Molten\nNaCl', 65, 220, 150, 260);
addLabel('Iron\nscreen', 65, 290, 230, 340);
addLabel('Cathode (-)', 150, 530, 165, 430);
addLabel('Anode (+)', 420, 530, 380, 440);

addLabel('Inlet for\nNaCl', 740, 130, 550, 135);
addLabel('Liquid\nNa metal', 740, 210, 640, 220);
addLabel('Cl₂ outlet', 730, 25);
addLabel('Na outlet', 740, 290);


// ── Interactivity Logic ──
window.toggle_powerState = function(on) {
  if (on) {
    bubblesGroup.show();
    naDropsGroup.show();
    wirePos.stroke({color: '#e74c3c'});  // Active Red (+)
    wireNeg1.stroke({color: '#3498db'}); // Active Blue (-)
    wireNeg2.stroke({color: '#3498db'});
  } else {
    bubblesGroup.hide();
    naDropsGroup.hide();
    wirePos.stroke({color: '#95a5a6'});
    wireNeg1.stroke({color: '#95a5a6'});
    wireNeg2.stroke({color: '#95a5a6'});
  }
};

// ── Demo Steps Orchestration ──
const steps = [
  {
    title: "The Cell at Rest",
    narration: "Molten NaCl fills the cell. The central anode and outer cathode are separated by an iron screen, waiting for an electrical current.",
    state: { powerState: false }
  },
  {
    title: "Electrolysis and Separation",
    narration: "When voltage is applied, Cl₂ gas bubbles form at the anode and rise into the central hood. Liquid Na forms at the cathode and floats into the side reservoir. The iron screen prevents them from mixing and recombining.",
    state: { powerState: true }
  }
];

let currentStep = 0;
function applyStep(idx) {
  currentStep = Math.max(0, Math.min(idx, steps.length - 1));
  const step = steps[currentStep];

  document.getElementById('demoNarration').innerHTML = `<strong>${step.title}</strong><br/>${step.narration}`;
  document.getElementById('stepLabel').textContent = `${currentStep + 1} / ${steps.length}`;

  const powerCb = document.getElementById('powerStateInput');
  powerCb.checked = step.state.powerState;
  toggle_powerState(step.state.powerState);
}

window.prevStep = function() { applyStep(currentStep - 1); };
window.nextStep = function() { applyStep(currentStep + 1); };

// Initialize default state
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

